import { asciiBytesToString, asciiStringToBytes, concatBytes, equalBytes } from './bytes.mjs';
import { checksum4 } from './hash.mjs';

const ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const ZERO_CHAR = ALPHABET[0];
const BASE = 58n;
const BYTE_BASE = 256n;

const ALPHABET_MAP = new Map(
  Array.from(ALPHABET, (symbol, index) => [symbol, BigInt(index)]),
);

function normalizeBase58Input(value) {
  if (typeof value === 'string') {
    return value;
  }
  if (Array.isArray(value)) {
    return asciiBytesToString(value);
  }
  throw new TypeError('Base58 input must be a string or an array of byte values');
}

function countLeadingBytes(bytes) {
  let count = 0;
  while (count < bytes.length && bytes[count] === 0) {
    count += 1;
  }
  return count;
}

function countLeadingOnes(value) {
  let count = 0;
  while (count < value.length && value[count] === ZERO_CHAR) {
    count += 1;
  }
  return count;
}

function bytesToBigInt(bytes) {
  let value = 0n;
  for (const byte of bytes) {
    value = (value * BYTE_BASE) + BigInt(byte);
  }
  return value;
}

function bigIntToBytes(value) {
  if (value === 0n) {
    return [];
  }

  const bytes = [];
  let current = value;
  while (current > 0n) {
    bytes.push(Number(current % BYTE_BASE));
    current /= BYTE_BASE;
  }
  bytes.reverse();
  return bytes;
}

function encodeBigInt(value) {
  if (value === 0n) {
    return '';
  }

  let encoded = '';
  let current = value;
  while (current > 0n) {
    const remainder = Number(current % BASE);
    encoded = `${ALPHABET[remainder]}${encoded}`;
    current /= BASE;
  }
  return encoded;
}

export function b58encode(bytes) {
  const leadingZeros = countLeadingBytes(bytes);
  const encoded = encodeBigInt(bytesToBigInt(bytes));
  return asciiStringToBytes(`${ZERO_CHAR.repeat(leadingZeros)}${encoded}`);
}

export function b58decodeInt(value) {
  const text = normalizeBase58Input(value);
  let decoded = 0n;

  for (const symbol of text) {
    const digit = ALPHABET_MAP.get(symbol);
    if (digit === undefined) {
      throw new Error(`Invalid character '${symbol}'`);
    }
    decoded = (decoded * BASE) + digit;
  }

  return decoded;
}

export function b58decode(value) {
  const text = normalizeBase58Input(value);
  const leadingZeros = countLeadingOnes(text);
  const decoded = bigIntToBytes(b58decodeInt(text));
  return concatBytes(new Array(leadingZeros).fill(0), decoded);
}

export function b58encodeInt(value) {
  const numericValue = typeof value === 'bigint' ? value : BigInt(value);
  if (numericValue < 0n) {
    throw new RangeError('Negative integers are not supported');
  }
  if (numericValue === 0n) {
    return asciiStringToBytes(ZERO_CHAR);
  }
  return asciiStringToBytes(encodeBigInt(numericValue));
}

export function b58encodeCheck(bytes) {
  return b58encode(concatBytes(bytes, checksum4(bytes)));
}

export function b58decodeCheck(value) {
  const decoded = b58decode(value);
  if (decoded.length < 4) {
    throw new Error('Invalid checksum');
  }

  const payload = decoded.slice(0, -4);
